BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-12478'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='1T2834' OR source_url ~ '[?&]id=12478(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='dc5b2834-1349-4a08-911b-41fdee312478' OR slug='sam-bigland-factory-land-113-plots-1t2834' OR (abs(latitude-14.113101)<0.0001 AND abs(longitude-100.61449)<0.0001 AND abs(land_area_sqm-43788)<1)) THEN RAISE NOTICE 'SAM 1T2834 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, custom_project_name, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('dc5b2834-1349-4a08-911b-41fdee312478', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'บิ๊กแลนด์ แฟคตอรี่', 'ที่ดินบิ๊กแลนด์ แฟคตอรี่ คลองหลวง 113 แปลง รวม 27 ไร่ 1 งาน 47 ตร.ว.', 'รายละเอียดทรัพย์

ที่ดินเปล่าภายในโครงการบิ๊กแลนด์ แฟคตอรี่ ตำบลคลองหนึ่ง อำเภอคลองหลวง จังหวัดปทุมธานี เข้าจากถนนพหลโยธิน (ทล.1) ผ่านซอยสามารถ รวม 113 แปลง เนื้อที่ 27 ไร่ 1 งาน 47 ตร.ว. หรือ 10,947 ตร.ว. (43,788 ตร.ม.) ราคาประกาศขาย SAM 244,558,000 บาท รหัส 1T2834 ต้นทางแสดงราคาประมาณ 22,340 บาท/ตร.ว. ใช้ราคารวมเป็นหลัก

ลักษณะที่ดิน

เป็นแปลงย่อยภายในโครงการ ไม่ใช่ที่ดินผืนเดียวติดต่อกันทั้งหมด เนื่องจากมีถนนภายในโครงการคั่นระหว่างแปลง ขนาดแต่ละแปลงตั้งแต่ 23.7 ถึง 980.8 ตร.ว. โฉนดเลขที่ 44969–44972, 85388–85423, 85570–85607, 85699–85732 และ 85773 รวม 113 ฉบับ SAM ระบุผังเมืองสีม่วง ควรตรวจข้อกำหนดการใช้ประโยชน์ให้ตรงกับกิจการที่จะดำเนินการ

ข้อควรทราบเกี่ยวกับทรัพย์

SAM ระบุว่าทรัพย์อยู่ใกล้แนวสายไฟฟ้าแรงสูง 230,000 โวลต์ โดยมีระยะร่นจากจุดศูนย์กลางข้างละ 20.5 เมตร ผู้สนใจควรตรวจแนวสายไฟ พื้นที่ที่ได้รับผลกระทบและข้อกำหนดการใช้ประโยชน์กับหน่วยงานที่เกี่ยวข้องก่อนเสนอซื้อ ข้อมูลนี้ไม่ได้ยืนยันว่าทุกแปลงได้รับผลกระทบเท่ากัน

โฉนดเลขที่ 85773 เนื้อที่ 206.3 ตร.ว. ซึ่งรวมอยู่ในเนื้อที่ทั้งหมด ถูกจัดสรรไว้เป็นสาธารณูปโภคภายในโครงการประเภทโรงเรียนอนุบาล จึงไม่ควรนับเป็นพื้นที่พัฒนาได้โดยไม่มีข้อจำกัด

ทางเข้าซอยสามารถเป็นถนนส่วนบุคคลบนโฉนดเลขที่ 355 โดย SAM ระบุว่าจดภาระจำยอมให้แปลงทรัพย์แล้ว ผิวคอนกรีตกว้างประมาณ 16 เมตร เขตทางประมาณ 30 เมตร ส่วนถนนภายในโครงการมีเขตทางประมาณ 10 และ 14 เมตร แต่ต้นทางระบุว่าไม่มีสภาพทาง ผู้สนใจควรตรวจตำแหน่งแปลง สิทธิในการใช้ทางและสภาพการเข้าถึงแต่ละแปลงก่อนเสนอซื้อ

SAM มีทรัพย์รหัส 1T2428, 1T2831 และ 1T2833 ภายในโครงการเดียวกันด้วย ผังรวมแสดงหลายรหัส ประกาศนี้เฉพาะรหัส 1T2834 ไม่รวมที่ดินของรหัสอื่น

ทำเลและการเดินทาง

อยู่ในย่านที่อยู่อาศัย พาณิชยกรรมและอุตสาหกรรม สถานที่ใกล้เคียงตาม SAM ได้แก่ นิคมอุตสาหกรรมนวนคร โลตัส บิ๊กซีนวนคร โรงพยาบาลนวนคร ตลาดไทและมหาวิทยาลัยธรรมศาสตร์ จากรังสิตมุ่งหน้าวังน้อยบนถนนพหลโยธิน ถึงโชว์รูมโตโยต้า เฟรนส์ชิบช่วง กม.45–46 เลี้ยวซ้ายเข้าซอยสามารถประมาณ 400 เมตร ทรัพย์อยู่ภายในโครงการด้านซ้ายมือ

ภาพและข้อมูลต้นทาง

รูปจริงและผังจาก SAM รวม 9 ภาพหลังตัดรูปซ้ำ ภาพภาคสนามหลายภาพแสดงวันที่ 28 พฤษภาคม 2564 และ 20 เมษายน 2565 ควรตรวจสภาพปัจจุบัน พิกัด 14.113101, 100.614490 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิงของกลุ่มทรัพย์ ไม่ใช่พิกัดขอบเขตของทุกแปลง

ราคาและสถานะซื้อตรงตรวจจากหน้า SAM วันที่ 15 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 1T2834 เพื่อยืนยันรายการโฉนด ราคา สถานะพร้อมขาย การนัดชมและเงื่อนไขล่าสุด', 244558000, false, 43788, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'โครงการบิ๊กแลนด์ แฟคตอรี่ ซอยสามารถ', 'เข้าจากถนนพหลโยธินประมาณ 400 เมตร', 'ซอยสามารถ ถนนพหลโยธิน (ทล.1)', 14.113101, 100.61449, 'ปทุมธานี', 'คลองหลวง', 'คลองหนึ่ง', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-bigland-factory-land-113-plots-1t2834') RETURNING id INTO property_listing_id;
