INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=12478&keyref=', '1T2834', now(), 'Source checked2026-09-15. THB244558000;113 non-contiguous plots,total43788sqm. Utility kindergarten deed85773 206.3 sq.wah included. Private road355 easement according to SAM; internal roads unformed. Other project asset codes excluded.9 unique photos/plans after removing exact duplicate; field photos dated 2021-05-28 and 2022-04-20. Navigation/map agree. All-status query returned nearby listing1376 / 1T2428 only, a different disjoint deed set and area; no duplicate for 1T2834. SAM reports 230kV corridor and20.5m setback each side; verify affected parcels.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Bigland Factory Land, Khlong Luang — 113 Plots, THB244.558M', 'Vacant land in Bigland Factory, Khlong Nueng, Khlong Luang, Pathum Thani, accessed from Phahonyothin Highway 1 via Soi Samat. The 113 plots total 27 rai 1 ngan 47 sq.wah, or 10,947 sq.wah (43,788 sq.m.). SAM announced price THB244,558,000, asset1T2834. Source unit price is approximately THB22,340/sq.wah; the total price governs.

These are separate subplots divided by internal project roads, not one continuous site. Individual plots range from 23.7 to 980.8 sq.wah. Chanote ranges44969–44972, 85388–85423, 85570–85607, 85699–85732 and 85773 total113 certificates. SAM reports purple zoning; verify permitted use for the intended activity.

Material restrictions: SAM reports a nearby 230,000-volt transmission line and a setback of 20.5 metres on each side of its centreline. Verify the corridor, affected parcels and applicable restrictions before offering; this does not imply every plot is equally affected. deed85773,206.3 sq.wah included in the total, was allocated as a project public-utility kindergarten plot. Do not treat it as unrestricted development land. Soi Samat is private road deed355; SAM reports a registered easement benefiting the property, approximately16m concrete carriageway and30m right of way. Internal project rights of way are10m and14m, but SAM says they have no formed road condition. Verify each plot''s access, rights and boundaries before offering.

